fn cube_root(n: u8) -> u8 {
    // For u8 inputs (0..=255), the floored cube root is in 0..=6
    // because 6^3 = 216 <= 255 and 7^3 = 343 > 255.
    let n32 = n as u32;

    let mut r: u8 = 0;
    let mut next: u8 = 1;

    while next <= 6 {
        let c = (next as u32) * (next as u32) * (next as u32);
        if c > n32 {
            break;
        }
        r = next;
        next += 1;
    }

    r
}